-- Additive overload: preserve the installed number-only function and its ACL.
-- Display metadata is not an identity, authorization input, or confirmed name.
BEGIN;
SET LOCAL lock_timeout = '5s';
CREATE OR REPLACE FUNCTION public.maia_whatsapp_intake(p_whatsapp text, p_display_name text)
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'pg_catalog'
SET lock_timeout TO '5s'
AS $function$
DECLARE
  receipt jsonb;
  display_name text;
  tenant constant uuid := '0af00833-c1f7-42f4-9543-a5e0ff6f55fc';
BEGIN
  -- The original function retains phone validation, fixed tenant, ambiguity
  -- rejection, and transaction-scoped advisory + contacts table locks. Those
  -- locks remain held through the guarded name update in this same transaction.
  receipt := public.maia_whatsapp_intake(p_whatsapp);
  IF p_display_name IS NOT NULL
    AND char_length(p_display_name) BETWEEN 1 AND 120
    AND strpos(p_display_name, '@') = 0
